ysninger','Account Holder'=>'Kontohaver','IBAN'=>'IBAN','Copy IBAN'=>'Kopiér IBAN','SWIFT/BIC'=>'SWIFT/BIC','Copy SWIFT/BIC'=>'Kopiér SWIFT/BIC','Reference'=>'Reference','Copy Reference'=>'Kopiér reference','Revolut Payment'=>'Revolut-betaling','Revtag'=>'Revtag','Copy Revtag'=>'Kopiér Revtag','Pay via Revolut.me'=>'Betal via Revolut.me','New Booking Received'=>'Ny booking modtaget','Guest Details'=>'Gæsteoplysninger','customer detailName'=>'Navn','customer detailEmail'=>'E-mail','customer detailPhone'=>'Telefon','Special Requests'=>'Særlige ønsker','Booking Details'=>'Bookingdetaljer','Booking ID'=>'Booking-ID','accommodation unitRoom'=>'Værelse','Check-in'=>'Indtjekning','Check-out'=>'Udtjekning','Guests'=>'Gæster','Payment Method'=>'Betalingsmetode','Total Price'=>'Totalpris','Payment Type'=>'Betalingstype','Deposit'=>'Depositum','Full Payment'=>'Fuld betaling','Coupon Code'=>'Kuponkode','Coupon Discount'=>'Kuponrabat','Deposit Paid'=>'Depositum betalt','Remaining Balance'=>'Resterende beløb','Tax Breakdown'=>'Momsopgørelse','Subtotal (net)'=>'Subtotal (netto)','Accommodation Tax'=>'Overnatningsskat','Children Tax'=>'Børneskat','Extras Tax'=>'Tillægsafgift','Service Fee Tax'=>'Servicegebyr-skat','Total Tax'=>'Samlet skat','View Booking in Dashboard'=>'Vis booking i kontrolpanel','[%1$s] New Booking #%2$d from %3$s'=>'[%1$s] Ny booking #%2$d fra %3$s','Verify your identity - %s'=>'Bekræft din identitet - %s','Verify Your Identity'=>'Bekræft din identitet','Please use the following code to confirm your identity with our AI concierge. This code will expire in 20 minutes.'=>'Brug venligst følgende kode til at bekræfte din identitet hos vores AI-concierge. Koden udløber om 20 minutter.','If you did not request this code, please ignore this email.'=>'Hvis du ikke har anmodet om denne kode, kan du ignorere denne e-mail.','Stripe'=>'Stripe','PayPal'=>'PayPal','Pay on Arrival / Manual'=>'Betal ved ankomst / Manuelt','Search Rooms'=>'Søg Værelser','from %s'=>'fra %s','